Q: TfsTeamSettingsProcessor failure with &quot;You have not set your team field&quot; A: <p>To solve the issue in my case, I had to add 2 TfsTeamProjectEndpoint's for the source and target:</p>
<pre><code>      &quot;TfsTeamProjectEndpointSource&quot;: {
        &quot;EndpointType&quot;: &quot;TfsTeamProjectEndpoint&quot;,
        &quot;Collection&quot;: &quot;https://&lt;&lt;sourceUrl&gt;&gt;&quot;,
        &quot;Project&quot;: &quot;projectA&quot;
        &quot;AllowCrossProjectLinking&quot;: true,
        &quot;Authentication&quot;: {
          &quot;AuthenticationMode&quot;: &quot;AccessToken&quot;,
          &quot;AccessToken&quot;: &quot;xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx&quot;
        },
        &quot;ReflectedWorkItemIdField&quot;: &quot;Our.DevelopmentProcess.ReflectedWorkItemID&quot;,
        &quot;LanguageMaps&quot;: {
          &quot;AreaPath&quot;: &quot;Area&quot;,
          &quot;IterationPath&quot;: &quot;Iteration&quot;
        },
        &quot;ProductVersion&quot;: &quot;OnPremises&quot;
      },      
      &quot;TfsTeamProjectEndpointTarget&quot;: {
        &quot;EndpointType&quot;: &quot;TfsTeamProjectEndpoint&quot;,
        &quot;Collection&quot;: &quot;https://&lt;&lt;targetUrl&gt;&gt;&quot;,
        &quot;Project&quot;: &quot;projectB&quot;,
        &quot;Authentication&quot;: {
          &quot;AuthenticationMode&quot;: &quot;AccessToken&quot;,
          &quot;AccessToken&quot;: &quot;yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy&quot;
        },
        &quot;ReflectedWorkItemIdField&quot;: &quot;Our.DevelopmentProcess.ReflectedWorkItemID&quot;,
        &quot;LanguageMaps&quot;: {
          &quot;AreaPath&quot;: &quot;Area&quot;,
          &quot;IterationPath&quot;: &quot;Iteration&quot;
        },
        &quot;ProductVersion&quot;: &quot;OnPremises&quot;
      },
</code></pre>
